#!/usr/bin/env node
/**
 * GO-SEARCH-1 Worker A — Search Index Generator
 *
 * Generates ONE canonical `src/data/search-index.json` from existing canonical
 * metadata ONLY (all JSON under src/data/). No content is duplicated into the
 * index; every item traces to a canonical source. Never run this by hand to
 * check output — Worker D runs it as part of the build pipeline.
 *
 * CONTRACT — generated search-index.json schema:
 * {
 *   "version": "1.0.0",
 *   "updated": "<YYYY-MM-DD>",
 *   "note": "Generated by scripts/generate-search-index.mjs — do not edit manually.",
 *   "items": [
 *     {
 *       "id": "unique-stable-id",
 *       "section": "about|dashboard|assessment|evidence|documents|news|activities|knowledge",
 *       "type": "about|dashboard|category|issue|indicator|evidence|document|document-page|news|activities|knowledge",
 *       "title": ["th", "en"],      // always [string,string]; '' when absent
 *       "context": ["th", "en"],    // always [string,string]; '' when absent
 *       "keywords": ["th", "en"],   // always [string,string]; '' when absent
 *       "route": "/canonical/path/",
 *       "routeKind": "page",
 *       "category": ["th", "en"] or null,
 *       "year": null or number,
 *       "fileType": null or "PDF"/"XLSX"
 *     }
 *   ]
 * }
 *
 * Rules: reuse metadata only, never duplicate content, never invent
 * relationships/routes/keywords. title/context/keywords are ALWAYS
 * [string,string] (empty strings when absent) — nullable only for
 * category/year/fileType. Routes are canonical paths WITHOUT locale/base
 * prefix — the search page applies locale + base at render time.
 *
 * Dependencies: node:fs, node:path, node:url only. No external deps, no TS.
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

// --- Paths ------------------------------------------------------------------
const REPO_ROOT = fileURLToPath(new URL('..', import.meta.url));
const DATA_DIR = path.join(REPO_ROOT, 'src', 'data');
const PUBLIC_DIR = path.join(REPO_ROOT, 'public');
// Optional --output <path> override, used by validate-search-index.mjs to
// regenerate to a temp file for drift comparison. When absent, the canonical
// committed index is written as before. (Additive — GO-SEARCH-1 Worker D.)
const outArgIndex = process.argv.indexOf('--output');
const OUT_PATH =
  outArgIndex !== -1 && process.argv[outArgIndex + 1]
    ? process.argv[outArgIndex + 1]
    : path.join(DATA_DIR, 'search-index.json');

// --- Helpers ----------------------------------------------------------------
/** Read + parse a JSON file relative to src/data/. Fails loudly if missing. */
function readJson(relPath) {
  const filePath = path.join(DATA_DIR, relPath);
  return JSON.parse(readFileSync(filePath, 'utf8'));
}

/** Join non-empty strings into one space-separated keyword blob. */
function cat(parts) {
  return parts.filter((p) => p !== null && p !== undefined && p !== '').join(' ');
}

/** Schema-compliant fileType: only PDF/XLSX are representable. */
function fileTypeOf(value) {
  if (value === 'PDF' || value === 'XLSX') return value;
  return null;
}

/** Infer fileType from a public path extension (derived, not invented). */
function fileTypeFromPath(p) {
  const ext = path.extname(p).toLowerCase();
  if (ext === '.pdf') return 'PDF';
  if (ext === '.xlsx' || ext === '.xls') return 'XLSX';
  return null;
}

/** Deterministic comparator (code-unit order — stable across Node versions). */
function cmp(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

// --- Canonical sources ------------------------------------------------------
const categoriesData = readJson(path.join('criteria', 'categories.json'));
const issuesData = readJson(path.join('criteria', 'issues.json'));
const indicatorsData = readJson(path.join('criteria', 'indicators.json'));
const evidenceData = readJson('evidence-index.json');
const aboutPagesData = readJson(path.join('about', 'pages.json'));
const documentsData = readJson(path.join('about', 'documents.json'));
const summariesData = readJson(path.join('about', 'document-summaries.json'));
const aboutDocsData = readJson(path.join('about', 'about-documents.json'));
const kpisData = readJson('dashboard-kpi.json');
const hubsData = readJson(path.join('content', 'hubs.json'));

// Indexes over canonical data (lookups only — no invented relationships).
const categories = categoriesData.categories;
const categoryByCode = new Map(categories.map((c) => [c.code, c]));
/** Bilingual parent-category title for a category code, or null. */
function categoryTitleFor(code) {
  const c = categoryByCode.get(code);
  return c ? [c.title.th, c.title.en] : null;
}

const summariesByDoc = new Map(
  summariesData.summaries.map((s) => [s.documentId, s]),
);

const items = [];

// --- 1. Categories (assessment / category) -----------------------------------
// categories.json → categories[] {code, title:{th,en}, summary:{th,en}}
for (const c of categories) {
  items.push({
    id: c.code,
    section: 'assessment',
    type: 'category',
    title: [c.title.th, c.title.en],
    context: [c.summary.th, c.summary.en],
    keywords: [cat([c.title.th, c.summary.th, c.code, c.id]), cat([c.title.en, c.summary.en, c.code, c.id])],
    route: `/categories/${c.code}/`,
    routeKind: 'page',
    category: [c.title.th, c.title.en],
    year: null,
    fileType: null,
  });
}

// --- 2. Issues (assessment / issue) ------------------------------------------
// issues.json → issues[] {id, code, categoryCode, title:{th,en}}
for (const i of issuesData.issues) {
  const parent = categoryTitleFor(i.categoryCode);
  items.push({
    id: i.code,
    section: 'assessment',
    type: 'issue',
    title: [i.title.th, i.title.en],
    context: ['', ''],
    keywords: [
      cat([i.title.th, parent ? parent[0] : null, i.code, i.id]),
      cat([i.title.en, parent ? parent[1] : null, i.code, i.id]),
    ],
    route: `/categories/${i.categoryCode}/`,
    routeKind: 'page',
    category: parent,
    year: null,
    fileType: null,
  });
}

// --- 3. Indicators (assessment / indicator) ----------------------------------
// indicators.json → indicators[] {id, code, categoryCode, title:{th,en}, requirementSummary:{th,en}}
for (const ind of indicatorsData.indicators) {
  const parent = categoryTitleFor(ind.categoryCode);
  items.push({
    id: ind.id,
    section: 'assessment',
    type: 'indicator',
    title: [ind.title.th, ind.title.en],
    context: [ind.requirementSummary.th, ind.requirementSummary.en],
    keywords: [
      cat([ind.title.th, ind.requirementSummary.th, parent ? parent[0] : null, ind.code, ind.id]),
      cat([ind.title.en, ind.requirementSummary.en, parent ? parent[1] : null, ind.code, ind.id]),
    ],
    route: `/indicators/${ind.id}/`,
    routeKind: 'page',
    category: parent,
    year: null,
    fileType: null,
  });
}

// --- 4. Evidence (evidence / evidence) ---------------------------------------
// evidence-index.json → items[] {id, title, titleTh, description, descriptionTh, categoryId, year, fileType, indicatorCodes}
for (const e of evidenceData.items) {
  const parent = categoryTitleFor(e.categoryId);
  const codes = Array.isArray(e.indicatorCodes) ? e.indicatorCodes : [];
  items.push({
    id: e.id,
    section: 'evidence',
    type: 'evidence',
    title: [e.titleTh, e.title],
    context: [e.descriptionTh, e.description],
    keywords: [
      cat([e.titleTh, e.descriptionTh, parent ? parent[0] : null, e.id, ...codes, e.year]),
      cat([e.title, e.description, parent ? parent[1] : null, e.id, ...codes, e.year]),
    ],
    route: `/evidence/${e.id}/`,
    routeKind: 'page',
    category: parent,
    year: typeof e.year === 'number' ? e.year : null,
    fileType: fileTypeOf(e.fileType),
  });
}

// --- 5. About pages (about / about) ------------------------------------------
// about/pages.json → pages[] {id, route, titleTh, titleEn, descriptionTh, descriptionEn}
// Only the frozen About set is canonical.
const FROZEN_ABOUT = new Set([
  'about-index',
  'about-policy',
  'about-goals',
  'about-scope',
  'about-committee',
  'about-action-plan',
  'about-feedback',
]);
for (const p of aboutPagesData.pages) {
  if (!FROZEN_ABOUT.has(p.id)) continue;
  items.push({
    id: p.id,
    section: 'about',
    type: 'about',
    title: [p.titleTh, p.titleEn],
    context: [p.descriptionTh, p.descriptionEn],
    keywords: [cat([p.titleTh, p.descriptionTh, p.id]), cat([p.titleEn, p.descriptionEn, p.id])],
    route: p.route,
    routeKind: 'page',
    category: null,
    year: null,
    fileType: null,
  });
}

// --- 6. Documents (documents / document) -------------------------------------
// about/documents.json → documents[] {id, titleTh, titleEn, documentType, documentYear, pathPublic, publicInternal, summaryStatus}
// Include ONLY: publicInternal === "public" AND summaryStatus !== "DUPLICATE_FILE"
// AND the file exists on disk at public/<pathPublic>.
// Summaries from about/document-summaries.json merge into keywords only.
for (const d of documentsData.documents) {
  if (d.publicInternal !== 'public') continue;
  if (d.summaryStatus === 'DUPLICATE_FILE') continue;
  if (!d.pathPublic) continue;
  const onDisk = path.join(PUBLIC_DIR, d.pathPublic.replace(/^[/\\]+/, ''));
  if (!existsSync(onDisk)) continue;
  const summary = summariesByDoc.get(d.id);
  const yearNum = d.documentYear ?? d.year ?? null;
  items.push({
    id: d.id,
    section: 'documents',
    type: 'document',
    title: [d.titleTh, d.titleEn],
    context: ['', ''],
    keywords: [
      cat([d.titleTh, d.documentType, summary ? summary.summaryTh : null, d.id, yearNum]),
      cat([d.titleEn, d.documentType, summary ? summary.summaryEn : null, d.id, yearNum]),
    ],
    route: d.pathPublic,
    routeKind: 'file',
    category: [d.documentType, d.documentType],
    year: typeof yearNum === 'number' ? yearNum : null,
    fileType: fileTypeOf(d.fileType) ?? fileTypeFromPath(d.pathPublic),
  });
}

// --- 7. Document pages by category (documents / document-page) ---------------
// about/about-documents.json maps About pages to document IDs (no category
// mapping present), so per-category doc counts are not trivially derivable.
// Use a generic bilingual label unless a trivial `categories` mapping exists.
let docCountByCategory = null;
if (aboutDocsData && aboutDocsData.categories && typeof aboutDocsData.categories === 'object') {
  docCountByCategory = {};
  for (const [code, v] of Object.entries(aboutDocsData.categories)) {
    const docs = Array.isArray(v) ? v : v && Array.isArray(v.documents) ? v.documents : [];
    docCountByCategory[code] = docs.length;
  }
}
for (const c of categories) {
  const count = docCountByCategory ? docCountByCategory[c.code] : undefined;
  const ctxTh = count !== undefined ? `${count} เอกสารในหมวดนี้` : 'เอกสารที่เกี่ยวข้องในหมวดนี้';
  const ctxEn = count !== undefined ? `${count} documents in this category` : 'Related documents in this category';
  items.push({
    id: `docpage-${c.code}`,
    section: 'documents',
    type: 'document-page',
    title: [c.title.th, c.title.en],
    context: [ctxTh, ctxEn],
    keywords: [cat([c.title.th, ctxTh, c.code]), cat([c.title.en, ctxEn, c.code])],
    route: `/documents/${c.code}/`,
    routeKind: 'page',
    category: [c.title.th, c.title.en],
    year: null,
    fileType: null,
  });
}

// --- 8. Dashboards (dashboard / dashboard) -----------------------------------
// dashboard-kpi.json → kpis[] {id, label, labelTh, description, descriptionTh, categoryId}
// Deduplicate by id; only ids in the frozen valid set are canonical.
const VALID_DASHBOARD_IDS = new Set(['energy', 'water', 'fuel', 'paper', 'waste', 'ghg']);
const seenDashboardIds = new Set();
for (const k of kpisData.kpis) {
  if (!VALID_DASHBOARD_IDS.has(k.id)) continue;
  if (seenDashboardIds.has(k.id)) continue;
  seenDashboardIds.add(k.id);
  const parent = categoryTitleFor(k.categoryId);
  items.push({
    id: k.id,
    section: 'dashboard',
    type: 'dashboard',
    title: [k.labelTh, k.label],
    context: [k.descriptionTh, k.description],
    keywords: [
      cat([k.labelTh, k.descriptionTh, parent ? parent[0] : null, k.id]),
      cat([k.label, k.description, parent ? parent[1] : null, k.id]),
    ],
    route: `/dashboard/${k.id}/`,
    routeKind: 'page',
    category: parent,
    year: null,
    fileType: null,
  });
}

// --- 9. Content hubs (news / activities / knowledge) -------------------------
// content/hubs.json → hubs.news / hubs.activities / hubs.knowledge
// One hub-level entry plus one entry per slot in slots[] (route = hub route).
const HUB_ROUTES = {
  news: '/news/',
  activities: '/activities/',
  knowledge: '/knowledge/',
};
for (const [hubKey, hub] of Object.entries(hubsData.hubs)) {
  const route = HUB_ROUTES[hubKey];
  items.push({
    id: hubKey,
    section: hubKey,
    type: hubKey,
    title: [hub.titleTh, hub.titleEn],
    context: [hub.descriptionTh, hub.descriptionEn],
    keywords: [cat([hub.titleTh, hub.descriptionTh, hubKey]), cat([hub.titleEn, hub.descriptionEn, hubKey])],
    route,
    routeKind: 'page',
    category: null,
    year: null,
    fileType: null,
  });
  (hub.slots || []).forEach((slot, idx) => {
    const slotId = `${hubKey}-slot-${idx + 1}`;
    items.push({
      id: slotId,
      section: hubKey,
      type: hubKey,
      title: [slot.titleTh, slot.titleEn],
      context: [slot.excerptTh, slot.excerptEn],
      keywords: [cat([slot.titleTh, slot.excerptTh, slotId]), cat([slot.titleEn, slot.excerptEn, slotId])],
      route,
      routeKind: 'page',
      category: null,
      year: null,
      fileType: null,
    });
  });
}

// --- Validation --------------------------------------------------------------
const ids = items.map((i) => i.id);
const dupIds = ids.filter((id, i) => ids.indexOf(id) !== i);
if (dupIds.length > 0) {
  throw new Error(`generate-search-index: duplicate item ids: ${[...new Set(dupIds)].join(', ')}`);
}
for (const it of items) {
  if (!it.id || !it.route) {
    throw new Error(`generate-search-index: item missing id/route: ${JSON.stringify(it)}`);
  }
}

// --- Assemble + deterministic sort -------------------------------------------
// Sort by section, then type, then title-en (stable across environments).
items.sort((a, b) => cmp(a.section, b.section) || cmp(a.type, b.type) || cmp(a.title[1], b.title[1]));

const index = {
  version: '1.0.0',
  updated: new Date().toISOString().slice(0, 10),
  note: 'Generated by scripts/generate-search-index.mjs — do not edit manually.',
  items,
};

mkdirSync(path.dirname(OUT_PATH), { recursive: true });
writeFileSync(OUT_PATH, `${JSON.stringify(index, null, 2)}\n`, 'utf8');

// --- Runtime summary (for Worker D QA) ---------------------------------------
const perSection = {};
for (const it of items) {
  perSection[it.section] = (perSection[it.section] || 0) + 1;
}
console.log(`Generated ${OUT_PATH}`);
console.log(`Total items: ${items.length}`);
for (const [section, count] of Object.entries(perSection).sort((a, b) => cmp(a[0], b[0]))) {
  console.log(`  ${section}: ${count}`);
}
